import { useState, type ComponentProps } from 'react'
import { Icon } from '@/lib/icon'
import { cn } from '@/lib/utils'
import styles from './Avatar.module.css'

export interface AvatarProps extends ComponentProps<'span'> {
  size?: 'xs' | 'sm' | 'md' | 'lg'
  imageSrc?: string
  /** Who this is. Without it the avatar is decorative and hidden from assistive tech. */
  imageAlt?: string
  /** Shown when there is no image, or it fails to load. One or two letters. */
  initials?: string
  appearance?: 'circle' | 'square'
}

export function Avatar({
  size = 'sm',
  imageSrc,
  imageAlt,
  initials,
  appearance = 'circle',
  className,
  ...props
}: AvatarProps) {
  // Keyed by src, so a new imageSrc gets a fresh attempt instead of staying
  // on the fallback from the last one that failed.
  const [failedSrc, setFailedSrc] = useState<string>()
  // An empty string is no image, not a request for the page's own URL.
  const showImage = !!imageSrc && failedSrc !== imageSrc

  return (
    <span
      // The label lives on the container so image, initials and placeholder
      // all announce the same thing: the person, not "S R" or nothing.
      role={imageAlt ? 'img' : undefined}
      aria-label={imageAlt}
      aria-hidden={imageAlt ? undefined : true}
      className={cn(styles.avatar, styles[size], styles[appearance], className)}
      {...props}
    >
      {showImage ? (
        <img
          src={imageSrc}
          alt=""
          className={styles.image}
          onError={() => setFailedSrc(imageSrc)}
        />
      ) : initials ? (
        <span className={styles.initials}>{initials}</span>
      ) : (
        <Icon name="user" className={styles.placeholder} />
      )}
    </span>
  )
}

.avatar {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  overflow: hidden;
  background: var(--secondary);
  color: var(--secondary-foreground);
  font-family: var(--font-sans);
  font-weight: 500;
  line-height: 1;
  user-select: none;
  vertical-align: middle;
}

.xs {
  inline-size: var(--space-6);
  block-size: var(--space-6);
  font-size: var(--text-body-sm);
}

.sm {
  inline-size: var(--space-8);
  block-size: var(--space-8);
  font-size: var(--text-body-sm);
}

.md {
  inline-size: var(--space-10);
  block-size: var(--space-10);
  font-size: var(--text-body);
}

.lg {
  inline-size: var(--space-12);
  block-size: var(--space-12);
  font-size: var(--text-body-lg);
}

/* Always round, whatever the Theme's radius preset: a circle is the shape,
   not a corner setting. */
.circle {
  border-radius: 9999px;
}

.square {
  border-radius: var(--radius-md);
}

.image {
  inline-size: 100%;
  block-size: 100%;
  object-fit: cover;
}

.initials {
  text-transform: uppercase;
}

/* A fraction rather than a token so the icon scales with all four sizes:
   60% leaves the same optical margin as initials at each one. */
.placeholder {
  inline-size: 60%;
  block-size: 60%;
  color: var(--muted-foreground);
}
